/**
 * Voice notes — recording, storing the audio, and turning it into text.
 *
 * The audio is kept, not discarded after transcription. That is the difference
 * between a voice note and dictation: transcription is lossy about tone,
 * hesitation and emphasis, and a writer replaying their own half-formed thought
 * hears things the transcript does not carry. So the Blob lives in IndexedDB
 * beside the folios, and the transcript is the searchable surface over it.
 *
 * Transcription follows the same provider chain as everything else: the
 * writer's own key first, then the Pro-gated hosted endpoint.
 */

import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import {
  runClientVoiceTranscribe,
  hasConfiguredVoiceProvider,
} from "./ai-client";
import { getCachedAiSettings } from "./ai-orchestrator";
import { loadVoiceNoteBlob, saveVoiceNoteBlob } from "./idb";
import { createAppError, normalizeApplicationError } from "./application-errors";
import type { AppError } from "../types/application-errors";

/** Recording stops itself here. Long enough for a real thought, short enough
 *  that a forgotten open mic can't fill the disk or the API bill. */
export const MAX_RECORDING_MS = 3 * 60_000;

/** Preferred container. Falls back through what the browser actually supports. */
const CANDIDATE_MIME_TYPES = [
  "audio/webm;codecs=opus",
  "audio/webm",
  "audio/ogg;codecs=opus",
  "audio/mp4",
];

export function pickRecordingMimeType(): string {
  if (typeof MediaRecorder === "undefined") return "audio/webm";
  for (const type of CANDIDATE_MIME_TYPES) {
    if (MediaRecorder.isTypeSupported(type)) return type;
  }
  return "";
}

export function canRecord(): boolean {
  return (
    typeof navigator !== "undefined" &&
    !!navigator.mediaDevices?.getUserMedia &&
    typeof MediaRecorder !== "undefined"
  );
}

export interface Recording {
  blob: Blob;
  durationMs: number;
  mimeType: string;
}

export interface RecorderHandle {
  /** Resolve with the finished recording. */
  stop: () => Promise<Recording>;
  /** Abandon the recording and release the microphone. */
  cancel: () => void;
  /** Current input level, 0-1, for a live meter. */
  level: () => number;
}

/**
 * Start recording. Rejects with a structured error when the microphone is
 * unavailable or permission is refused — the caller shows it, and must not
 * treat a refusal as a bug.
 */
export async function startRecording(): Promise<RecorderHandle> {
  if (!canRecord()) {
    throw createAppError("CONFIGURATION_ERROR", {
      source: "application",
      recovery: { action: "none", canRetry: false },
      metadata: {
        feature: "voice-notes",
        operation: "record",
        reason: "no-media-recorder",
      },
    });
  }

  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (err) {
    throw normalizeApplicationError(err, {
      source: "application",
      metadata: { feature: "voice-notes", operation: "microphone-permission" },
    });
  }

  const mimeType = pickRecordingMimeType();
  const recorder = new MediaRecorder(
    stream,
    mimeType ? { mimeType } : undefined,
  );
  const chunks: Blob[] = [];
  recorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  // A live level meter, so the writer can see the mic is actually hearing
  // them. Failing to build one is not a reason to fail the recording.
  let analyser: AnalyserNode | null = null;
  let audioContext: AudioContext | null = null;
  let levelData: Uint8Array | null = null;
  try {
    audioContext = new AudioContext();
    const source = audioContext.createMediaStreamSource(stream);
    analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);
    levelData = new Uint8Array(analyser.frequencyBinCount);
  } catch {
    analyser = null;
  }

  const startedAt = Date.now();
  recorder.start();

  const release = () => {
    for (const track of stream.getTracks()) track.stop();
    void audioContext?.close().catch(() => {});
  };

  let autoStop: ReturnType<typeof setTimeout> | null = null;

  const stop = () =>
    new Promise<Recording>((resolve) => {
      if (autoStop) clearTimeout(autoStop);
      const finish = () => {
        release();
        resolve({
          blob: new Blob(chunks, { type: mimeType || "audio/webm" }),
          durationMs: Date.now() - startedAt,
          mimeType: mimeType || "audio/webm",
        });
      };
      if (recorder.state === "inactive") {
        finish();
        return;
      }
      recorder.onstop = finish;
      recorder.stop();
    });

  autoStop = setTimeout(() => void stop(), MAX_RECORDING_MS);

  return {
    stop,
    cancel: () => {
      if (autoStop) clearTimeout(autoStop);
      if (recorder.state !== "inactive") {
        recorder.onstop = null;
        recorder.stop();
      }
      release();
    },
    level: () => {
      if (!analyser || !levelData) return 0;
      analyser.getByteFrequencyData(levelData);
      let sum = 0;
      for (const v of levelData) sum += v;
      return Math.min(1, sum / levelData.length / 128);
    },
  };
}

/* ── Persistence ────────────────────────────────────────────────── */

export async function storeVoiceNote(
  id: string,
  blob: Blob,
): Promise<void> {
  await saveVoiceNoteBlob(id, blob);
}

export async function readVoiceNote(id: string): Promise<Blob | null> {
  return loadVoiceNoteBlob(id);
}

/* ── Transcription ──────────────────────────────────────────────── */

export interface TranscriptionOutcome {
  text: string;
  provider: string;
}

async function blobToBase64(blob: Blob): Promise<string> {
  const buffer = await blob.arrayBuffer();
  const bytes = new Uint8Array(buffer);
  // Chunked so a three-minute recording doesn't blow the argument limit of
  // String.fromCharCode with a single spread.
  let binary = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

/**
 * Turn a recording into text. BYOK first, then the Pro-gated hosted endpoint.
 * Throws a structured {@link AppError} when neither is reachable, so the
 * caller can offer the right recovery instead of a generic failure.
 */
export async function transcribeRecording(args: {
  blob: Blob;
  mimeType: string;
  client?: ConvexClient | null;
  /** Terms likely to appear — the brief's title and audience work well. */
  prompt?: string;
}): Promise<TranscriptionOutcome> {
  const settings = await getCachedAiSettings();

  // Gate on a voice-capable provider, not a language one: a writer with only
  // Fish Audio configured must still be able to transcribe.
  if (hasConfiguredVoiceProvider(settings)) {
    const result = await runClientVoiceTranscribe(
      { audio: args.blob, prompt: args.prompt },
      settings,
    );
    if (result?.text) {
      return { text: result.text, provider: `client-${result.provider}` };
    }
  }

  if (args.client) {
    const res = (await args.client.action(api.voice.transcribeSpeech, {
      audioBase64: await blobToBase64(args.blob),
      mimeType: args.mimeType,
      prompt: args.prompt,
    })) as { text: string; provider: string };
    return { text: res.text, provider: res.provider };
  }

  throw createAppError("CONFIGURATION_ERROR", {
    source: "application",
    recovery: { action: "choose-provider", canRetry: false },
    metadata: { feature: "voice-notes", operation: "transcribe" },
  }) as AppError;
}

/** Human-readable duration for a note's label. */
export function formatDuration(ms: number): string {
  const total = Math.round(ms / 1000);
  const mins = Math.floor(total / 60);
  const secs = total % 60;
  return `${mins}:${secs.toString().padStart(2, "0")}`;
}

"use node";

import { action } from "./_generated/server";
import { v } from "convex/values";
import { internal } from "./_generated/api";
import { consumeRateLimit, RATE_LIMITS } from "./lib/rateLimit";
import { isProSubscription } from "./lib/entitlement";

const OPENAI_AUDIO_BASE = "https://api.openai.com/v1";
const MAX_SPEECH_CHARS = 4096;

const audioFormatValidator = v.union(
  v.literal("mp3"),
  v.literal("opus"),
  v.literal("aac"),
  v.literal("flac"),
  v.literal("wav"),
  v.literal("pcm"),
);

export const synthesizeSpeech = action({
  args: {
    text: v.string(),
    model: v.optional(v.string()),
    voice: v.optional(v.string()),
    instructions: v.optional(v.string()),
    responseFormat: v.optional(audioFormatValidator),
    speed: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");

    // Rate limit: each synthesis is a paid OpenAI call. 20 per minute per
    // user is well above any real reading flow, and stops abuse of the
    // hosted key.
    await consumeRateLimit(ctx, {
      action: "voice:synthesize",
      identifier: identity.tokenIdentifier,
      ...RATE_LIMITS.voiceSynthesize,
    });

    const subscription = await ctx.runQuery(
      internal.payments.getSubscriptionByUserId,
      {
        userId: identity.tokenIdentifier,
      },
    );
    if (!isProSubscription(subscription)) {
      throw new Error("Voice narration is a Pro feature.");
    }

    const apiKey =
      process.env.VOICE_OPENAI_API_KEY ?? process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("Hosted voice is not configured.");

    const input = args.text.trim().slice(0, MAX_SPEECH_CHARS);
    if (!input) throw new Error("Nothing to read.");

    const responseFormat = args.responseFormat ?? "mp3";
    const res = await fetch(`${OPENAI_AUDIO_BASE}/audio/speech`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${apiKey}`,
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model:
          args.model ?? process.env.VOICE_OPENAI_MODEL ?? "gpt-4o-mini-tts",
        input,
        voice: args.voice ?? process.env.VOICE_OPENAI_VOICE ?? "alloy",
        response_format: responseFormat,
        ...(args.instructions ? { instructions: args.instructions } : {}),
        ...(args.speed ? { speed: clampSpeed(args.speed) } : {}),
      }),
    });

    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Hosted voice failed (${res.status}): ${detail.slice(0, 240)}`,
      );
    }

    return {
      audioBase64: Buffer.from(await res.arrayBuffer()).toString("base64"),
      mimeType: audioMimeType(responseFormat),
      responseFormat,
      provider: "openai",
      model: args.model ?? process.env.VOICE_OPENAI_MODEL ?? "gpt-4o-mini-tts",
      voice: args.voice ?? process.env.VOICE_OPENAI_VOICE ?? "alloy",
    };
  },
});

/** Roughly three minutes of Opus at 32kbps, base64-encoded. */
const MAX_TRANSCRIBE_BYTES = 12 * 1024 * 1024;

/**
 * Transcribe a recorded voice note.
 *
 * The mirror image of {@link synthesizeSpeech}: same identity check, same rate
 * limiter, same Pro gate, same key resolution. The audio arrives base64-encoded
 * because Convex actions take JSON — the client keeps the original Blob locally,
 * so nothing is lost by re-encoding for the wire.
 */
export const transcribeSpeech = action({
  args: {
    audioBase64: v.string(),
    mimeType: v.string(),
    /** Optional nudge for proper nouns and jargon the recording will contain. */
    prompt: v.optional(v.string()),
    model: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");

    await consumeRateLimit(ctx, {
      action: "voice:transcribe",
      identifier: identity.tokenIdentifier,
      ...RATE_LIMITS.voiceTranscribe,
    });

    const subscription = await ctx.runQuery(
      internal.payments.getSubscriptionByUserId,
      {
        userId: identity.tokenIdentifier,
      },
    );
    if (!isProSubscription(subscription)) {
      throw new Error("Hosted transcription is a Pro feature.");
    }

    const apiKey =
      process.env.VOICE_OPENAI_API_KEY ?? process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("Hosted transcription is not configured.");

    const bytes = Buffer.from(args.audioBase64, "base64");
    if (bytes.length === 0) throw new Error("Nothing to transcribe.");
    if (bytes.length > MAX_TRANSCRIBE_BYTES) {
      throw new Error("That recording is too long to transcribe.");
    }

    const model =
      args.model ??
      process.env.VOICE_OPENAI_TRANSCRIBE_MODEL ??
      "gpt-4o-mini-transcribe";

    const form = new FormData();
    form.append(
      "file",
      new Blob([new Uint8Array(bytes)], { type: args.mimeType }),
      `note.${extensionForMime(args.mimeType)}`,
    );
    form.append("model", model);
    form.append("response_format", "json");
    if (args.prompt?.trim()) form.append("prompt", args.prompt.trim().slice(0, 800));

    const res = await fetch(`${OPENAI_AUDIO_BASE}/audio/transcriptions`, {
      method: "POST",
      headers: { authorization: `Bearer ${apiKey}` },
      body: form,
    });

    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(
        `Hosted transcription failed (${res.status}): ${detail.slice(0, 240)}`,
      );
    }

    const data = (await res.json()) as { text?: string };
    return {
      text: typeof data.text === "string" ? data.text.trim() : "",
      provider: "openai",
      model,
    };
  },
});

/** The file extension the transcription endpoint expects for a MIME type. */
function extensionForMime(mimeType: string): string {
  const base = mimeType.split(";")[0].trim().toLowerCase();
  switch (base) {
    case "audio/webm":
      return "webm";
    case "audio/ogg":
      return "ogg";
    case "audio/mp4":
    case "audio/m4a":
      return "m4a";
    case "audio/wav":
    case "audio/x-wav":
      return "wav";
    case "audio/mpeg":
      return "mp3";
    default:
      return "webm";
  }
}

function clampSpeed(speed: number): number {
  if (!Number.isFinite(speed)) return 1;
  return Math.max(0.25, Math.min(4, speed));
}

function audioMimeType(format: string): string {
  switch (format) {
    case "opus":
      return "audio/opus";
    case "aac":
      return "audio/aac";
    case "flac":
      return "audio/flac";
    case "wav":
      return "audio/wav";
    case "pcm":
      return "audio/L16";
    case "mp3":
    default:
      return "audio/mpeg";
  }
}

